/*!
 * wega-music-endless0.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "endless0" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * ENDLESS (Endless Theme, floors 1-10) - supplied by the player. Loops with a crossfade from 161.6 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-endless0.js] load wega-music.js first"); return; }
  D.endless0 = {
    title: "ENDLESS (Endless Theme, floors 1-10)",
    credit: "supplied by the player",
    duration: 164.519,
    loopStart: 0.0,
    loopEnd: 161.6,
    xfade: 2.5,
    gain: 1.0,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("endless0") < 0) W.tracks.push("endless0");
  if (W.onPack) W.onPack("endless0");
})(typeof window !== "undefined" ? window : globalThis);
